<!-- Step Indicator Bar -->
<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var stepClass = GetStepClass(stepIndex);
        <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
            <div class="step-circle">
                @if (stepIndex < CurrentStep)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </div>
            <div class="step-label">@StepNames[stepIndex]</div>
        </div>
        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger mt-3">@ErrorMessage</div>
}

<!-- Step 1: Personal Info -->
@if (CurrentStep == 0)
{
    <div class="form-section">
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name *</label>
            <input type="text" class="form-control" @bind="FullName" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email *</label>
            <input type="email" class="form-control" @bind="Email" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone *</label>
            <input type="tel" class="form-control" @bind="Phone" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address *</label>
            <textarea class="form-control" @bind="Address"></textarea>
        </div>
        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsLoading">
                @if (IsLoading) { <span>Validating...</span> } else { <span>Next</span> }
            </button>
        </div>
    </div>
}

<!-- Step 2: Work History -->
@if (CurrentStep == 1)
{
    <div class="form-section">
        <h3>Work History</h3>
        @for (int i = 0; i < WorkEntries.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <h5>Position @(index + 1)</h5>
                @if (WorkEntries.Count > 1)
                {
                    <button class="btn btn-sm btn-outline-danger float-end" @onclick="() => RemoveWorkEntry(index)">Remove</button>
                }
                <div class="mb-2">
                    <label class="form-label">Company Name *</label>
                    <input type="text" class="form-control" @bind="WorkEntries[index].Company" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Job Title *</label>
                    <input type="text" class="form-control" @bind="WorkEntries[index].Title" />
                </div>
                <div class="row mb-2">
                    <div class="col-md-4">
                        <label class="form-label">Start Date *</label>
                        <input type="date" class="form-control" @bind="WorkEntries[index].StartDate" />
                    </div>
                    <div class="col-md-4">
                        <label class="form-label">End Date</label>
                        <input type="date" class="form-control" @bind="WorkEntries[index].EndDate" disabled="@WorkEntries[index].IsCurrent" />
                    </div>
                    <div class="col-md-4 d-flex align-items-end">
                        <div class="form-check">
                            <input type="checkbox" class="form-check-input" @bind="WorkEntries[index].IsCurrent" />
                            <label class="form-check-label">Currently working here</label>
                        </div>
                    </div>
                </div>
                <div class="mb-2">
                    <label class="form-label">Description</label>
                    <textarea class="form-control" @bind="WorkEntries[index].Description"></textarea>
                </div>
            </div>
        }
        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="Back">Back</button>
            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
        </div>
    </div>
}

<!-- Step 3: References -->
@if (CurrentStep == 2)
{
    <div class="form-section">
        <h3>References</h3>
        @for (int i = 0; i < References.Count; i++)
        {
            var index = i;
            <div class="card mb-3 p-3">
                <h5>Reference @(index + 1)</h5>
                @if (References.Count > 2)
                {
                    <button class="btn btn-sm btn-outline-danger float-end" @onclick="() => RemoveReference(index)">Remove</button>
                }
                <div class="mb-2">
                    <label class="form-label">Name *</label>
                    <input type="text" class="form-control" @bind="References[index].Name" />
                </div>
                <div class="mb-2">
                    <label class="form-label">Relationship *</label>
                    <input type="text" class="form-control" @bind="References[index].Relationship" />
                </div>
                <div class="row mb-2">
                    <div class="col-md-6">
                        <label class="form-label">Email *</label>
                        <input type="email" class="form-control" @bind="References[index].Email" />
                    </div>
                    <div class="col-md-6">
                        <label class="form-label">Phone *</label>
                        <input type="tel" class="form-control" @bind="References[index].Phone" />
                    </div>
                </div>
            </div>
        }
        @if (References.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
        }
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="Back">Back</button>
            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
        </div>
    </div>
}

<!-- Step 4: Cover Letter -->
@if (CurrentStep == 3)
{
    <div class="form-section">
        <h3>Cover Letter</h3>
        <div class="mb-3">
            <textarea class="form-control" rows="12" @bind="CoverLetter" @bind:event="oninput" maxlength="2000"></textarea>
            <div class="text-muted mt-1">@CoverLetter.Length / 2000 characters</div>
        </div>
        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="Back">Back</button>
            <button class="btn btn-primary" @onclick="NextFromCoverLetter">Next</button>
        </div>
    </div>
}

<!-- Step 5: Review & Submit -->
@if (CurrentStep == 4)
{
    <div class="form-section">
        <h3>Review & Submit</h3>

        @if (IsSubmitted)
        {
            <div class="alert alert-success">
                <h4>Application Submitted Successfully!</h4>
                <p>Your application ID is: <strong>@ApplicationId</strong></p>
                <p>Thank you for applying. We will be in touch soon.</p>
            </div>
        }
        else
        {
            <!-- Personal Info Review -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between">
                    <h5>Personal Information</h5>
                    <a href="javascript:void(0)" @onclick='() => GoToStep(0)'>Edit</a>
                </div>
                <p><strong>Name:</strong> @FullName</p>
                <p><strong>Email:</strong> @Email</p>
                <p><strong>Phone:</strong> @Phone</p>
                <p><strong>Address:</strong> @Address</p>
            </div>

            <!-- Work History Review -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between">
                    <h5>Work History</h5>
                    <a href="javascript:void(0)" @onclick='() => GoToStep(1)'>Edit</a>
                </div>
                @foreach (var entry in WorkEntries)
                {
                    <div class="mb-2 ps-3 border-start">
                        <p><strong>@entry.Title</strong> at @entry.Company</p>
                        <p>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))</p>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p>@entry.Description</p>
                        }
                    </div>
                }
            </div>

            <!-- References Review -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between">
                    <h5>References</h5>
                    <a href="javascript:void(0)" @onclick='() => GoToStep(2)'>Edit</a>
                </div>
                @foreach (var reference in References)
                {
                    <div class="mb-2 ps-3 border-start">
                        <p><strong>@reference.Name</strong> (@reference.Relationship)</p>
                        <p>@reference.Email | @reference.Phone</p>
                    </div>
                }
            </div>

            <!-- Cover Letter Review -->
            <div class="card mb-3 p-3">
                <div class="d-flex justify-content-between">
                    <h5>Cover Letter</h5>
                    <a href="javascript:void(0)" @onclick='() => GoToStep(3)'>Edit</a>
                </div>
                <p style="white-space: pre-wrap;">@CoverLetter</p>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="Back">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsLoading">
                    @if (IsLoading) { <span>Submitting...</span> } else { <span>Submit Application</span> }
                </button>
            </div>
        }
    </div>
}

<style>
    .step-indicator {
        display: flex;
        align-items: center;
        justify-content: center;
        margin: 2rem 0;
    }

    .step {
        display: flex;
        flex-direction: column;
        align-items: center;
        cursor: default;
        opacity: 0.4;
    }

    .step.active {
        opacity: 1;
    }

    .step.completed {
        opacity: 1;
        cursor: pointer;
    }

    .step-circle {
        width: 36px;
        height: 36px;
        border-radius: 50%;
        background: #dee2e6;
        display: flex;
        align-items: center;
        justify-content: center;
        font-weight: bold;
        margin-bottom: 4px;
    }

    .step.active .step-circle {
        background: #0d6efd;
        color: white;
    }

    .step.completed .step-circle {
        background: #198754;
        color: white;
    }

    .step-label {
        font-size: 0.75rem;
        text-align: center;
        max-width: 80px;
    }

    .step-connector {
        flex: 1;
        height: 2px;
        background: #dee2e6;
        margin: 0 8px;
        margin-bottom: 20px;
    }

    .step-connector.completed {
        background: #198754;
    }

    .form-section {
        max-width: 720px;
        margin: 0 auto;
    }
</style>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    private int CurrentStep { get; set; } = 0;
    private bool IsLoading { get; set; }
    private bool IsSubmitted { get; set; }
    private int? ApplicationId { get; set; }
    private string ErrorMessage { get; set; } = "";

    // Step 1 - Personal Info
    private string FullName { get; set; } = "";
    private string Email { get; set; } = "";
    private string Phone { get; set; } = "";
    private string Address { get; set; } = "";

    // Step 2 - Work History
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 - References
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 - Cover Letter
    private string CoverLetter { get; set; } = "";

    private string GetStepClass(int step)
    {
        if (step == CurrentStep) return "active";
        if (step < CurrentStep) return "completed";
        return "";
    }

    private void GoToStep(int step)
    {
        if (step < CurrentStep)
        {
            CurrentStep = step;
            ErrorMessage = "";
        }
    }

    private void Back()
    {
        if (CurrentStep > 0)
        {
            CurrentStep--;
            ErrorMessage = "";
        }
    }

    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = "";

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsLoading = true;
        try
        {
            var emailValid = await ApplicationService.ValidateEmailAsync(Email);
            if (!emailValid)
            {
                ErrorMessage = "Please enter a valid email address.";
                return;
            }
            CurrentStep = 1;
        }
        finally
        {
            IsLoading = false;
        }
    }

    private void NextFromWorkHistory()
    {
        ErrorMessage = "";
        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate == default)
            {
                ErrorMessage = "Please fill in company, title, and start date for all positions.";
                return;
            }
        }
        CurrentStep = 2;
    }

    private void NextFromReferences()
    {
        ErrorMessage = "";
        foreach (var reference in References)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                ErrorMessage = "Please fill in all fields for each reference.";
                return;
            }
        }
        CurrentStep = 3;
    }

    private void NextFromCoverLetter()
    {
        ErrorMessage = "";
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter.";
            return;
        }
        CurrentStep = 4;
    }

    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());

    private void RemoveWorkEntry(int index)
    {
        if (WorkEntries.Count > 1) WorkEntries.RemoveAt(index);
    }

    private void AddReference()
    {
        if (References.Count < 3) References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2) References.RemoveAt(index);
    }

    private async Task SubmitApplication()
    {
        IsLoading = true;
        ErrorMessage = "";
        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description ?? "")).ToList());
            var refs = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, refs, CoverLetter);

            ApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsLoading = false;
        }
    }

    private class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}
